import{_ as e,o as t,c as n,a1 as r}from"./chunks/framework.CblolBb6.js";const m=JSON.parse('{"title":"Materi Pelatihan WebGIS","description":"","frontmatter":{},"headers":[],"relativePath":"materi-pelatihan.md","filePath":"materi-pelatihan.md"}'),i={name:"materi-pelatihan.md"};function s(d,a,p,l,o,u){return t(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="materi-pelatihan-webgis" tabindex="-1">Materi Pelatihan WebGIS <a class="header-anchor" href="#materi-pelatihan-webgis" aria-label="Permalink to &quot;Materi Pelatihan WebGIS&quot;">​</a></h1><p>Materi ini disusun sebagai panduan belajar WebGIS (Web Geographic Information System) secara bertahap, dari tingkat dasar sampai lanjutan. Penyampaiannya menekankan praktik langsung, sehingga peserta dapat mengulang setiap tahap secara mandiri.</p><p>Materi dibagi menurut <strong>hari pelaksanaan</strong>, mengikuti susunan acara pelatihan periode 15 sampai 18 September 2026. Setiap halaman hari memuat jadwal sesi, daftar materi, dan penanda bagian yang belum tersedia.</p><h2 id="materi-per-hari" tabindex="-1">Materi per Hari <a class="header-anchor" href="#materi-per-hari" aria-label="Permalink to &quot;Materi per Hari&quot;">​</a></h2><p><a href="./hari-1/"><strong>Hari 1 - Dasar GIS, QGIS, dan Peta 2D</strong></a></p><p>Teori dasar GIS dan alur kerja WebGIS, pengolahan data spasial di QGIS, dasar HTML/CSS/JavaScript, serta peta 2D dengan Leaflet. Termasuk penyiapan lingkungan kerja: Visual Studio Code, Node.js, Next.js, dan Git.</p><p><a href="./hari-2/"><strong>Hari 2 - Peta 3D, Basis Data Spasial, dan GeoServer</strong></a></p><p>Peta 3D dengan CesiumJS, basis data PostgreSQL dan PostGIS, serta GeoServer sebagai layanan penyaji data spasial.</p><p><a href="./hari-3/"><strong>Hari 3 - Backend, Autentikasi, dan Deployment</strong></a></p><p>Prisma ORM, CRUD API, NextAuth, lalu deployment ke Google Cloud Platform: VM, Docker, Nginx, dan HTTPS.</p><p><a href="./hari-4/"><strong>Hari 4 - Penyempurnaan dan Studi Kasus</strong></a></p><p>Penyempurnaan aplikasi, implementasi data Gaussian Splatting, dan review alur WebGIS.</p><h2 id="status-kelengkapan" tabindex="-1">Status Kelengkapan <a class="header-anchor" href="#status-kelengkapan" aria-label="Permalink to &quot;Status Kelengkapan&quot;">​</a></h2><p>Sebagian sesi pada susunan acara belum punya berkas materi di repositori ini, dan saat ini disampaikan langsung oleh instruktur. Bagian yang belum tersedia ditandai di halaman masing-masing hari, bukan dikosongkan tanpa keterangan.</p><table tabindex="0"><thead><tr><th>Hari</th><th>Sesi yang sudah tersedia</th><th>Sesi yang belum tersedia</th></tr></thead><tbody><tr><td>Hari 1</td><td>Persiapan lingkungan, peta 2D dengan Leaflet</td><td>Teori dasar GIS, praktik QGIS</td></tr><tr><td>Hari 2</td><td>Peta 3D dengan CesiumJS, basis data spasial, GeoServer</td><td>Penjelasan ORM Prisma dan App Routes</td></tr><tr><td>Hari 3</td><td>Prisma dan API login, NextAuth, deployment ke GCP</td><td>Penjelasan CRUD API, penjelasan GCP dan Docker</td></tr><tr><td>Hari 4</td><td>Belum ada</td><td>Seluruh sesi Hari 4</td></tr></tbody></table><h2 id="berkas-pendukung" tabindex="-1">Berkas Pendukung <a class="header-anchor" href="#berkas-pendukung" aria-label="Permalink to &quot;Berkas Pendukung&quot;">​</a></h2><p>Beberapa halaman menyertakan berkas yang bisa diunduh langsung, misalnya <code>docker-compose.yml</code>, <code>nginx.conf</code>, dan <code>.env.example</code> pada <a href="./hari-3/praktik-11-deploy/konfigurasi-project.html">Konfigurasi Project</a>. Berkas lain dibagikan instruktur melalui folder berkas pelatihan.</p>',17)])])}const g=e(i,[["render",s]]);export{m as __pageData,g as default};
